`non_local_checks__UseNonLocal` <- function(...) {
  argtypes <- mapply(class, list(...));
  argv <- list(...);
  argc <- length(argtypes);
  f <- NULL;
# dispatch functions 3
  if (argc == 1) {
    if ( extends(argtypes[1], '_p_attention_cnn__AttentionResNetConfig') && length(argv[[1]]) == 1 ) {
      f <- non_local_checks__UseNonLocal__SWIG_2;
    }
  } else if (argc == 2) {
    if (( extends(argtypes[1], '_p_attention_cnn__AttentionResNetConfig') && length(argv[[1]]) == 1 ) && ( is.logical(argv[[2]]) && length(argv[[2]]) == 1 )) {
      f <- non_local_checks__UseNonLocal__SWIG_1;
    }
  } else if (argc == 3) {
    if (( extends(argtypes[1], '_p_attention_cnn__AttentionResNetConfig') && length(argv[[1]]) == 1 ) && ( is.logical(argv[[2]]) && length(argv[[2]]) == 1 ) && ( is.logical(argv[[3]]) && length(argv[[3]]) == 1 )) {
      f <- non_local_checks__UseNonLocal__SWIG_0;
    }
  };
  if (is.null(f)) {
    stop("cannot find overloaded function for non_local_checks__UseNonLocal with argtypes (",toString(argtypes),")");
  };
  f(...);
}

