  argtypes <- mapply(class, list(...));
  argv <- list(...);
  argc <- length(argtypes);
  f <- NULL;
# dispatch functions 2
  if (argc == 1) {
    if ( is.integer(argv[[1]]) || is.numeric(argv[[1]]) ) {
      f <- fcos__FcosPoints__SWIG_1;
    }
  } else if (argc == 2) {
    if (( is.integer(argv[[1]]) || is.numeric(argv[[1]]) ) && ( is.numeric(argv[[2]]) && length(argv[[2]]) == 1 )) {
      f <- fcos__FcosPoints__SWIG_0;
    }
  };
  if (is.null(f)) {
    stop("cannot find overloaded function for fcos__FcosPoints with argtypes (",toString(argtypes),")");
  };
  f(...);
}

