    if (( extends(argtypes[1], '_p_panoptic__PqStatsHandle') && length(argv[[1]]) == 1 ) && ( is.integer(argv[[2]]) || is.numeric(argv[[2]]) )) {
      f <- panoptic__PanopticQuality__SWIG_1;
    }
  } else if (argc == 3) {
    if (( extends(argtypes[1], '_p_panoptic__PqStatsHandle') && length(argv[[1]]) == 1 ) && ( is.integer(argv[[2]]) || is.numeric(argv[[2]]) ) && ( (is.integer(argv[[3]]) || is.numeric(argv[[3]])) && length(argv[[3]]) == 1 )) {
      f <- panoptic__PanopticQuality__SWIG_0;
    }
  };
  if (is.null(f)) {
    stop("cannot find overloaded function for panoptic__PanopticQuality with argtypes (",toString(argtypes),")");
  };
  f(...);
}

